{"command":"create","path":"/workspace/source/packages/privacy/src/erasure-lifecycle.ts","file_text":"import type { PoolClient } from 'pg';
import { pool, transaction } from '../../database/src/pool.js';
import { boundedExponentialBackoffSeconds } from '../../operations/src/retry-policy.js';
import { toErasureErrorCode } from './errors.js';

export interface ClaimedErasureRequest {
  id: string;
  merchant_id: string;
  customer_id: string;
  attempts: number;
}

/**
 * Recovers erasure requests whose worker crashed mid-processing. Left as
 * `failed` (not `completed`) so a retry is required before the request can
 * ever be reported as done; regulatory erasure must never be recovered
 * unless every step actually ran.
 */
export async function recoverExpiredErasureLeases(): Promise<number> {
  const result = await pool.query(
    `UPDATE customers.erasure_requests
     SET status='failed', available_at=now(), locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
         last_error=COALESCE(last_error, 'worker_lease_expired')
     WHERE status='processing' AND lease_expires_at < now()`,
  );
  return result.rowCount ?? 0;
}

export async function claimErasureRequest(workerId: string, leaseSeconds = 120): Promise<ClaimedErasureRequest | undefined> {
  return await transaction(async (client) => {
    const result = await client.query<ClaimedErasureRequest>(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, locked_by=$1, locked_at=now(),
           lease_expires_at=now()+($2 || ' seconds')::interval, updated_at=now()
       WHERE id=(SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed') AND available_at<=now()
         ORDER BY available_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
       RETURNING id,merchant_id,customer_id,attempts`,
      [workerId, leaseSeconds],
    );
    return result.rows[0];
  });
}

export async function completeErasureRequest(request: ClaimedErasureRequest): Promise<void> {
  await pool.query(
    `UPDATE customers.erasure_requests
     SET status='completed', completed_at=now(), updated_at=now(), last_error=NULL,
         locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
     WHERE id=$1`,
    [request.id],
  );
}

export async function failErasureRequest(client: PoolClient, request: ClaimedErasureRequest, error: unknown): Promise<void> {
  const code = toErasureErrorCode(error);
  await client.query(
    `UPDATE customers.erasure_requests
     SET status='failed', available_at=now()+($2 || ' seconds')::interval, last_error=$3, updated_at=now(),
         locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
     WHERE id=$1`,
    [request.id, boundedExponentialBackoffSeconds(request.attempts), code],
  );
}
"}

{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { transaction } from '../../../packages/database/src/pool.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';

export interface ErasureRequestView {
  id: string;
  customerId: string;
  status: ErasureRequestRow['status'];
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

function toView(row: ErasureRequestRow): ErasureRequestView {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  /**
   * Starts (or resumes) an erasure workflow for a customer. Idempotency keys
   * are scoped to the merchant: reusing a key for the same customer replays
   * the same request, reusing it for a different customer is rejected, and a
   * brand-new key for a customer that already has a request simply returns
   * that existing request instead of starting a second workflow.
   */
  async requestErasure(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestView> {
    return await transaction(async (client) => {
      const existingKey = await this.repository.findIdempotencyKey(client, merchantId, idempotencyKey);
      if (existingKey) {
        if (existingKey.customer_id !== customerId) {
          throw Object.assign(new Error('idempotency key reused for a different customer'), { statusCode: 409 });
        }
        const request = await this.repository.findByCustomer(client, merchantId, customerId);
        return toView(request!);
      }

      const customer = await this.repository.findCustomerMerchant(merchantId, customerId);
      if (!customer) throw Object.assign(new Error('customer not found'), { statusCode: 404 });

      const existingRequest = await this.repository.findByCustomer(client, merchantId, customerId);
      const request = existingRequest ?? await this.repository.create(client, merchantId, customerId);
      await this.repository.recordIdempotencyKey(client, merchantId, idempotencyKey, customerId, request.id);
      return toView(request);
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestView | undefined> {
    const request = await this.repository.find(merchantId, requestId);
    return request ? toView(request) : undefined;
  }
}
"}

